    n = len(grid)
    m = len(grid[0])
    visited = [[False]*m for _ in range(n)]
    def bfs(i,j):
        stack = [(i,j)]
        visited[i][j] = True
        while stack:
            x,y = stack.pop()
            for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx, ny = x+dx, y+dy
                if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and grid[nx][ny]==1:
                    visited[nx][ny] = True
                    stack.append((nx,ny))
    count = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j]==1 and not visited[i][j]:
                bfs(i,j)
                count += 1
    return count

